-- SEPARATE REVIEW: 14 additions only; never run during migration/build/startup.
-- Operator must approve item/prices, rights, staging identity and backend verification.
-- In the same SQL session only after approval:
-- SET nookstep.catalog_additions_approved = 'true';
DO $$ BEGIN
 IF current_setting('nookstep.catalog_additions_approved',true) IS DISTINCT FROM 'true' THEN
  RAISE EXCEPTION 'STOP: separate catalog, rights, project and compatibility approval required';
 END IF;
 IF to_regprocedure('public.save_room_layout_surfaces(jsonb,bigint)') IS NULL THEN
  RAISE EXCEPTION 'STOP: multi-surface migration required';
 END IF;
END $$;
begin;
