as x(id text,name text,category text,price_coins integer,surface_type text,room_kind text,asset_path text,asset_variants jsonb,is_active boolean,sort_order smallint);
do $$ begin
 if exists(select 1 from proposed_room_expansion p join public.shop_items c using(id)
   where to_jsonb(p) is distinct from to_jsonb(c)) then
  raise exception 'STOP: existing catalog metadata differs; no overwrite or repricing allowed';
 end if;
end $$;
insert into public.shop_items(id,name,category,price_coins,surface_type,room_kind,asset_path,asset_variants,is_active,sort_order)
select id,name,category,price_coins,surface_type,room_kind,asset_path,asset_variants,is_active,sort_order
from proposed_room_expansion
on conflict (id) do nothing;
commit;
-- No Auth, profile, inventory, ledger, session or placement mutations.
